package com.personal.assistant.module.scheduler.service;import com.personal.assistant.common.exception.BusinessException;import com.personal.assistant.module.scheduler.dto.SchedulerJobRequest;import com.personal.assistant.module.scheduler.entity.SchedulerJob;import com.personal.assistant.module.scheduler.job.JobHandler;import com.personal.assistant.module.scheduler.mapper.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;import org.quartz.Scheduler;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class)class SchedulerJobServiceTest{@Mock SchedulerJobMapper jobs;@Mock SchedulerJobLogMapper logs;@Mock Scheduler scheduler;SchedulerJobService service;@BeforeEach void setUp(){JobHandler h=new JobHandler(){public String type(){return "REMINDER_SCAN";}public String execute(String c){return "ok";}};service=new SchedulerJobService(jobs,logs,scheduler,List.of(h));}@Test void rejectsInvalidCron(){var r=new SchedulerJobRequest("扫描","REMINDER_SCAN","not-cron",true,"{}");assertThrows(BusinessException.class,()->service.create(1L,r));}@Test void rejectsUnknownJobType(){var r=new SchedulerJobRequest("未知","UNKNOWN","0 0/5 * * * ?",true,"{}");assertThrows(BusinessException.class,()->service.create(1L,r));}@Test void disabledJobDoesNotExecute(){SchedulerJob x=new SchedulerJob();x.setId(2L);x.setEnabled(false);when(jobs.selectById(2L)).thenReturn(x);service.execute(2L);verifyNoInteractions(logs);}}